const s = input.state;
const e = input.event;
function remainingOf(items) {
  var n = 0;
  for (var i = 0; i < items.length; i++) { if (!items[i].done) n++; }
  return n;
}
function keyOf(v) {
  if (v && typeof v === 'object') return v.key;
  return typeof v === 'string' ? v : '';
}
if (e.type === 'action') {
  if (e.actionId === 'newItem') {
    var typed = typeof e.value === 'string' ? e.value : '';
    return { state: Object.assign({}, s, { newItem: typed.slice(0, 200) }) };
  }
  if (e.actionId === 'add') {
    var txt = (s.newItem || '').trim();
    if (txt.length > 0 && s.items.length < 100) {
      var items = s.items.concat([{ id: 't' + s.nextId, text: txt.slice(0, 200), done: false }]);
      return { state: Object.assign({}, s, { items: items, newItem: '', nextId: s.nextId + 1, remaining: remainingOf(items) }) };
    }
    return { state: s };
  }
  if (e.actionId === 'toggle') {
    var v = e.value;
    var key = keyOf(v);
    var val = (v && typeof v === 'object') ? (v.value === true) : true;
    var items2 = s.items.map(function (it) {
      return it.id === key ? Object.assign({}, it, { done: val }) : it;
    });
    return { state: Object.assign({}, s, { items: items2, remaining: remainingOf(items2) }) };
  }
  if (e.actionId === 'remove') {
    var key2 = keyOf(e.value);
    var items3 = s.items.filter(function (it) { return it.id !== key2; });
    return { state: Object.assign({}, s, { items: items3, remaining: remainingOf(items3) }) };
  }
  if (e.actionId === 'clearDone') {
    var items4 = s.items.filter(function (it) { return !it.done; });
    return { state: Object.assign({}, s, { items: items4, remaining: remainingOf(items4) }) };
  }
}
return { state: s };
